/**
 * @class DoubleAgent_ExtraWildGame
 */
cc.Class({
    extends: cc.Component,

    properties: {
        colWildItems:[cc.Node],
        jinbizhongjiang1:sp.Skeleton,
        jinbizhongjiang2:sp.Skeleton,   // 
        xialuo:sp.Skeleton,             // 下落动画
    },

    onLoad() {
        // 记录原始坐标
        this.colWildItems.forEach((v, i)=>{
            for(let j=0; j<=4; j++) {
                let item = v.getChildByName("xialuo_zengjia_0" + j);
                item.data = {originX:item.x, originY:item.y};
            }
        });
    },

    /**
     * 开始 自然掉落wild
     * @param {numb[][]} data
     * @returns {Promise<void>}
     */
    async startFallWild(data) {
        if(!data || data.length < 1) {
            return;
        }
        //await this._hideWilds();
        let maxRound = 0; // 掉落轮数
        data.forEach(v=>{
           maxRound = Math.max(maxRound, v.length);
        });

        for(let i=0; i<maxRound; i++) {
            if(!this._stopFall){
                await this._fallARound((i+1), data);
            }
        }
        this._stopFall = false;
    },

    //点击停止直接显示xialuo_zengjia
    showZengjiaWild(data){
        if(!data || data.length < 1) {
            return;
        }
        let index = 0;
        this._stopFall = true;
        data.forEach(v=>{
           let round = v.length;
           if(round > 0){
                let colNode = this.colWildItems[index];
                colNode.getChildByName("xialuo_01").active = false;
                colNode.getChildByName("xialuo_xunhuan_01").active = false;
                let feixingParticle = colNode.getChildByName("particle_feixing");
                feixingParticle.stopAllActions();
                feixingParticle.getComponent(cc.ParticleSystem).resetSystem();
                feixingParticle.active = false;
                for(let i=0;i<round;i++){
                    let zengjianode = colNode.getChildByName("xialuo_zengjia_0" + i);
                    zengjianode.cleanup();
                    zengjianode.stopAllActions();
                    zengjianode.active = true;
                    zengjianode.scale = 1;
                    let skl = zengjianode.getComponent(sp.Skeleton);
                    let endPos = skl.node.data;
                    skl.node.setPosition(endPos.originX, endPos.originY);
                }
           }
           index++;
        });
    },

    /**
     * 隐藏wild资源
     */
    hideWilds() {
        this.jinbizhongjiang2.node.active = false;
        let promiseArr = [];
        let scaleTime = 0.2;
        let maxdelay = 0;
        for(let i=0; i<5; i++) {
            let colNode = this.colWildItems[i];
            let xialuo_01 = colNode.getChildByName("xialuo_01");
            xialuo_01.active = false;
            let particle_feixing = colNode.getChildByName("particle_feixing");
            particle_feixing.active = false;
            let xialuo_xunhuan_01 = colNode.getChildByName("xialuo_xunhuan_01");
            xialuo_xunhuan_01.active = false;
            let zongjiang_01 = colNode.getChildByName("xialuo_zongjiang_01")
            zongjiang_01.active = false
            let delayTime = 0;
            for(let j=4; j>=0; j--) {
                let xialuo_zengjia = colNode.getChildByName("xialuo_zengjia_0" + j);
                if(xialuo_zengjia.active) {
                    cc.tween(xialuo_zengjia)
                        .delay(delayTime)
                        .to(scaleTime, {scale:0})
                        .call(()=>{
                            xialuo_zengjia.active = false;
                        })
                        .start();
                    delayTime += scaleTime;
                    // if(j == 0) {
                    //     promiseArr.push(SlotsFacade.delayTime(delayTime));
                    // }
                }
                
            }
            if(delayTime > maxdelay){
                maxdelay = delayTime;
            }
        }
        return maxdelay;
        // if(promiseArr.length) {
        //     await Promise.all(promiseArr);
        // }
    },

    /**
     * 一轮掉落
     * @param {number} round 论次
     * @param {numb[][]} data 掉落数据
     */
    async _fallARound(round, data) {
        SlotsFacade.soundMgr.playEffect("coin_drop");
        let promissArr = [];
        for(let i=0; i<data.length; i++) {
            if(data[i].length >= round) {
                promissArr.push(this._playATrace(round, i));
            }
        } 
        if(promissArr.length) {
            await Promise.all(promissArr);
        }
    },

    /**
     * 播放一个下落动画
     * @param {*} round 从1开始
     * @param {*} colIndex 从0开始
     */
    async _playATrace(round, colIndex, startPos) {
        let colNode = this.colWildItems[colIndex];
        // 初始化位置大小
        if(!startPos) {
            startPos = colNode.getChildByName("pos_start").getPosition();
        }
        let xialuoSpine = colNode.getChildByName("xialuo_zengjia_0" + (round-1)).getComponent(sp.Skeleton);
        xialuoSpine.node.setPosition(startPos.x, startPos.y);
        xialuoSpine.node.scale = 1;
        xialuoSpine.node.active = true;

        // 播放spine动画
        let startAniName = "animation" + (colIndex+1);
        let idleAniName = startAniName + "_" + (colIndex + 1);
        if(round > 1) {
            startAniName = "animation1_2";
            idleAniName = "animation1_1";
        }
        xialuoSpine.setAnimation(0, startAniName, false);
        xialuoSpine.setCompleteListener(()=>{
            xialuoSpine.setCompleteListener(null);
            xialuoSpine.setAnimation(0, idleAniName, false);
        });

        // 移动位置
        let endPos = xialuoSpine.node.data;
        cc.tween(xialuoSpine.node)
            .to(0.8, {x:endPos.originX, y:endPos.originY}, {easing:"cubicIn"})
            .call(()=>{
                let xialuo_01_spine =  colNode.getChildByName("xialuo_01").getComponent(sp.Skeleton);
                xialuo_01_spine.node.setPosition(endPos.originX, endPos.originY);
                xialuo_01_spine.node.active = true;
                xialuo_01_spine.setAnimation(0, "animation", false);
                xialuo_01_spine.setCompleteListener(()=>{
                    xialuo_01_spine.setCompleteListener(null);
                    let xialuo_xunhuan_01_spine = colNode.getChildByName("xialuo_xunhuan_01").getComponent(sp.Skeleton);
                    xialuo_xunhuan_01_spine.node.active = true;
                    xialuo_xunhuan_01_spine.setAnimation(0, "animation", true);
                });
            })
            .start();
        let feixingParticle = colNode.getChildByName("particle_feixing");
        feixingParticle.setPosition(startPos.x, startPos.y);
        feixingParticle.active = true;
        feixingParticle.stopAllActions();
        feixingParticle.getComponent(cc.ParticleSystem).resetSystem();
        cc.tween(feixingParticle)
            // .to(0.8, {x:endPos.originX, y:endPos.originY}, {easing:"cubicIn"})
            .to(0.8, {x:0, y:0}, {easing:"cubicIn"})
            .call(()=>{
                feixingParticle.active = false;
            })
            .start();
        await SlotsFacade.delayTime(0.81);
    },

    /**
     * 填充wild
     */
    async fillWilds() {
        // 宝箱填充 wilds 拼图
        let boxIdx = SlotsFacade.dm.getBoxIndex();
        let boxSpine = null;
        if(boxIdx > 0) {

            let symbol = SlotsFacade.slots.GetSymbolByIdx(boxIdx);
            boxSpine = symbol.node.getChildByName("w11").getComponent(sp.Skeleton);
            await this._fillWildsPuzzle(boxSpine);
        }

        if(SlotsFacade.dm.isCompletePuzzelWild()) {

            await this._showPrePuzzelGame();
            // wilds拼图释放wild
            await this._releasePuzzleWilds();
            // 隐藏中奖光效
            this.colWildItems.forEach(i => {
                i.getChildByName("xialuo_zongjiang_01").active = false;
            });
            // 宝箱释放wild
            await this._releaseBoxWilds(boxSpine);
        }
    },

    /**
     * 释放wild前奏动画
     */
    async _showPrePuzzelGame() {
        this.jinbizhongjiang1.node.active = true;
        this.jinbizhongjiang1.setAnimation(0, "animation", false);
        this.jinbizhongjiang1.setCompleteListener(()=>{
            this.jinbizhongjiang1.setCompleteListener(null);
            this.jinbizhongjiang2.node.active = true;
            this.jinbizhongjiang2.setAnimation(0, "animation", true);
            this.colWildItems.forEach(i => {
                let xialuo_zongjiang = i.getChildByName("xialuo_zongjiang_01").getComponent(sp.Skeleton);
                xialuo_zongjiang.node.active = true;
                xialuo_zongjiang.setAnimation(0, "animation", true);
            });
        });
        await SlotsFacade.delayTime(1.5);
    },

    /**
     * 填充wilds缺失拼图
     */
    async _fillWildsPuzzle(boxSpine) {
        let cols = SlotsFacade.dm.getLackPuzzleWildCols();
        if(cols.length < 1) {
            return;
        }
        SlotsFacade.soundMgr.playEffect("vault_coin");
        let startPos = boxSpine.node.convertToWorldSpaceAR(cc.v2(0, 0));
        boxSpine.node.active = true;
        boxSpine.setAnimation(0, "animation", false);
        SlotsFacade.delayTime(0.5);
        for(let i=0; i<cols.length; i++) {
            let colNode = this.colWildItems[cols[i]];
            let pos = colNode.convertToNodeSpaceAR(startPos);
            boxSpine.setAnimation(0, "animation3", false);
            this._playATrace(1, cols[i], pos);
        }
        await SlotsFacade.delayTime(1);
    },

    /**
     * 释放拼图wild(上翻wild)
     */
    async _releasePuzzleWilds() {
        let maxRound = 0; // 掉落轮数
        let  data = SlotsFacade.dm.getSpinData().randomData.fallWilds;
        data.forEach(v=>{
           maxRound = Math.max(maxRound, v.length);
        });
        if(maxRound > 0){
            //快速点击时 停止和上翻会同时进行 做个延时处理
            await SlotsFacade.delayTime(0.5);
        }

        for(let i=maxRound; i>0; i--) {
            await this._releaseARound(i, data);
        }
    },

    /**
     * 释放一轮 puzzle wilds
     * @param {number} round 论次
     * @param {numb[][]} data 掉落数据
     */
    async _releaseARound(round, data) {
        SlotsFacade.soundMgr.playEffect("coin_fly");
        let promissArr = [];
        for(let i=0; i<data.length; i++) {
            if(data[i].length >= round) {
                promissArr.push(this._releaseATrace(round, i, data[i][round-1]));
            }
        } 
        if(promissArr.length) {
            await Promise.all(promissArr);
        }
    },

    /**
     * 释放一个puzzle wild 动画
     * @param {*} round 从1开始
     * @param {*} colIndex 从0开始
     */
    async _releaseATrace(round, colIndex, itemIndex) {
        let colNode = this.colWildItems[colIndex];
        let xialuoSpine = colNode.getChildByName("xialuo_zengjia_0" + round).getComponent(sp.Skeleton);
        // 播放spine动画
        xialuoSpine.setAnimation(0, "animation1", false);
        // 移动位置
        let symbolItem = SlotsFacade.slots.GetSymbolByIdx(itemIndex);
        let endPos = colNode.convertToNodeSpaceAR(symbolItem.node.convertToWorldSpaceAR(cc.v2(0, 0)));
        cc.tween(xialuoSpine.node)
            .to(1, {x:endPos.x, y:endPos.y})
            .call(()=>{
                xialuoSpine.node.active = false;
                symbolItem.addWild();
            })
            .start();
        await SlotsFacade.delayTime(1.01);
    },
    
    /**
     * 释放宝箱wilds
     */
    async _releaseBoxWilds(boxSpine) {
        this._stopFall = false;
        let data = SlotsFacade.dm.getSpinData().randomData.bankWilds;
        SlotsFacade.delayTime(0.5);
        for(let i=0; i<data.length; i++) {
            await this._releaseABoxTrace([data[i]], boxSpine);
        }
    },

    /**
     * 释放一个宝箱 wild 动画
     * @param {*} itemIndex 
     */
    async _releaseABoxTrace(itemIndex, boxSpine) {
        SlotsFacade.soundMgr.playEffect("coin_fly");
        // 播放箱子动画
        boxSpine.setAnimation(0, "animation3", false);
        // 移动位置
        let symbolItem = SlotsFacade.slots.GetSymbolByIdx(itemIndex);
        let endPos = this.node.convertToNodeSpaceAR(symbolItem.node.convertToWorldSpaceAR(cc.v2(0, 0)));
        let startPos = this.xialuo.node.parent.convertToNodeSpaceAR(boxSpine.node.convertToWorldSpaceAR(cc.v2(0, 0)));
        let xialuoSpine = this.xialuo;
        xialuoSpine.node.active = true;
        xialuoSpine.node.x = startPos.x;
        xialuoSpine.node.y = startPos.y;
        cc.tween(xialuoSpine.node)
            .to(0.9, {x:endPos.x, y:endPos.y})
            .start();
        await new Promise(res=>{
            xialuoSpine.setAnimation(0, "animation1", false);
            xialuoSpine.setCompleteListener(()=>{
                xialuoSpine.setCompleteListener(null);
                xialuoSpine.node.active = false;
                symbolItem.addWild();
                res();
            });
        });
    },
});
