cc.Class({
    extends: require("LMSlots_Symbol_Base"),

    properties: {
        wildCount : 0,  // wild的数量
    },

    StartMove:function(){
        this._super();
        this.wildCount = 0;
        let wild = this.node.getChildByName("wild");
        wild.active = false;
    },

    /**
     * 添加wild倍数
     */
    addWild() {
        if(this.GetShowId() != 1) {
            this.ShowById(1, null);
        }
        this.wildCount += 1;
        let wild = this.node.getChildByName("wild");
        wild.active = true;
        let spine = wild.getChildByName("spine").getComponent(sp.Skeleton);
        spine.node.active = true;
        spine.setAnimation(0, "animation1", false);
        let wildMulti = null;
        if(this.wildCount == 1) {
            wildMulti = wild.getChildByName("wild_1").getComponent(sp.Skeleton);
            wild.getChildByName("wild_multi").active = false;
        }else {
            wildMulti = wild.getChildByName("wild_multi").getComponent(sp.Skeleton);
            wild.getChildByName("wild_1").active = false;
        }
        wildMulti.node.active =true;
        wildMulti.setAnimation(0, "animation" + this.wildCount, false);
        let wildlizibao = wild.getChildByName("wildlizibao");
        SlotsFacade.dm.playSpine(wildlizibao,'animation',false,()=>{
            wildlizibao.active = false;
        });
    },

    /**
     * 播放wild图标动画
     */
    playWild() {
        if(this._showNode){
            this._showNode.active = false;
        }
        let aniNode = this.setAnimationToTop(true)
        aniNode.active = true
        let wild = aniNode.getChildByName("wild");
        let spine = wild.getChildByName("spine").getComponent(sp.Skeleton);
        spine.node.active = true;
        spine.setAnimation(0, "animation1", false);
        let wildMulti = null;
        if(this.wildCount == 1) {
            wildMulti = wild.getChildByName("wild_1").getComponent(sp.Skeleton);
            wild.getChildByName("wild_multi").active = false;
        }else {
            wildMulti = wild.getChildByName("wild_multi").getComponent(sp.Skeleton);
            wild.getChildByName("wild_1").active = false;
        }
        wildMulti.node.active =true;
        wildMulti.setAnimation(0, "animation" + this.wildCount + "_1", true);
    },

    playWinAnimation() {
        if(this.GetShowId()==1) {
            this.playWild();
        }else {
            this._super();
        }
    },

    //直接改变符号
    changeSymboltoBaoxiang(){
        if(this._showNode){
            this._showNode.active = false
        }
        this._id = 11;
        let cfg = cc.vv.gameData.getGameCfg()
        this._showNode = cc.find(cfg.symbol[11].node,this.node)
        this._showNode.active = true
    },
});
