/**
 * 收集进度
 * @class DoubleAgent_CollectProgress
 */
cc.Class({
    extends: cc.Component,

    properties: {
        icon_energy:cc.Node,        // 能量收集图标
        btn_enter: cc.Node,         // 进入收集游戏按钮节点
        progressBar: cc.Node,       // 进度条节点
        spine_switch_tips: sp.Skeleton, // 收集打开关闭开关提示
        spine_full: sp.Skeleton,    // 集满能量条，能量条上的动画
        collect_track_particle:cc.Node, // 能量收集轨道粒子动画
        unlock_tips: cc.Node,       // 解锁提示

        _isOpen:false,   // 是否打开收集
    },

    onLoad() {
        this._initListener();
        this._init();
    },

    _initListener() {
        Global.registerEvent(cc.vv.gameData._EventId.SLOT_TOTALBET_UPDATED, ()=>{
            this.showCollect(false);
        },this);

        this.btn_enter.on(cc.Node.EventType.TOUCH_END, this._onEnterHandler.bind(this), this);
        this.progressBar.on(cc.Node.EventType.TOUCH_END, ()=>{
            if(!this._isOpen) {
                this._showTips(true);
            }
        }, this);
    },

    _init() {
        this.setProgress(SlotsFacade.dm.getCollectPercent());
        this.showCollect(true);
    },

    _onEnterHandler() {
        // 如果在免费中 返回
        if(SlotsFacade.dm.hasFree()) {
            return;
        }
        // 如果spin不可点击 返回
        if(!SlotsFacade.bottomCmp.GetSpinBtnState()) {
            return;
        }
        SlotsFacade.soundMgr.playEffect("btn_click");
        SlotsFacade.bottomCmp.ShowBtnsByState("moveing_1");
        SlotsFacade.collectGame.open(true, ()=>{
            SlotsFacade.bottomCmp.ShowBtnsByState("idle");
        });
    },

    /**
     * 显示提示
     */
    _showTips(boo) {
        SlotsFacade.soundMgr.playEffect("tips");
        if(this.unlock_tips.active) {
            this.unlock_tips.stopAllActions();
        }
        if(boo) {
            this.unlock_tips.active = true;
            this.unlock_tips.opacity = 0;
            cc.tween(this.unlock_tips)
                .to(1, {opacity:0xff})
                .delay(3)
                .to(1, {opacity:0})
                .call(()=>{
                    this.unlock_tips.active = false;
                })
                .start();
        }else {
            if(this.unlock_tips.active) {
                cc.tween(this.unlock_tips)
                    .to(1, {opacity:0})
                    .call(()=>{
                        this.unlock_tips.active = false;
                    })
                    .start();
            }
        }
    },

    /**
     * 收集能量
     * @param {Array<cc.Vec2>} globalPosArr
     * @param percent
     */
    async collectEnergy(globalPosArr, percent) {
        let endPos = this.icon_energy.getPosition();
        let promiseArr = [];
        globalPosArr.forEach(v=>{
            let pos = this.node.convertToNodeSpaceAR(v);
            let lz = cc.instantiate(this.collect_track_particle);
            lz.parent = this.node;
            lz.x = pos.x;
            lz.y = pos.y;
            lz.active = true;
            let p = lz.getComponent(cc.ParticleSystem);
            p.resetSystem();

            promiseArr.push(new Promise((res)=>{
                cc.tween(lz)
                    .to(0.5, {x:endPos.x, y:endPos.y})
                    .call(()=> {
                        lz.removeFromParent();
                        res();
                    })
                    .start();
            }));
        });
        SlotsFacade.soundMgr.playEffect("collect");
        await Promise.all(promiseArr);
        this.playCollectSpine();
        this.setProgress(percent, true);
    },

    //飞到收集栏spine播放
    playCollectSpine(){
        let collectsp = cc.find('collectsp',this.icon_energy);
        SlotsFacade.dm.playSpine(collectsp,'animation',false,null);
    },

    /**
     * 显示收集界面
     * @param isInit
     */
    showCollect(isInit) {
        let boo = SlotsFacade.dm.canCollect();
        if(boo) {
            if(!this._isOpen) {
                if(isInit) {
                    this.spine_switch_tips.node.active = false;
                }else {
                    SlotsFacade.soundMgr.playEffect("unlock");
                    this.spine_switch_tips.setAnimation(0, "animation1", false);
                }
            }
        }else {
            this.spine_switch_tips.node.active = true;
            if(isInit) {
                this.spine_switch_tips.setAnimation(0, "animation3", true);
            }else {
                if(this._isOpen) {
                    SlotsFacade.soundMgr.playEffect("lock");
                    this.spine_switch_tips.setAnimation(0, "animation2", false);
                }
            }
        }
        this._isOpen = boo;
    },

    /**
     * 播放收集完成动画
     */
    playCollectEnd() {
        return new Promise(res=> {
            SlotsFacade.soundMgr.playEffect("free_dialog_collect_show");
            this.spine_collect_end.node.active = true;
            this.spine_collect_end.setAnimation(0, "animation1", false);
            this.spine_collect_end.setCompleteListener(()=>{
                this.spine_collect_end.setCompleteListener(null);
                this.spine_collect_end.node.active = false;
                res();
            });
        });
    },

    /**
     * 设置进度
     * @param percent
     */
    setProgress(percent, needTransform) {
        percent = Math.min(1, percent);
        let w = this.progressBar.width;
        let spine = this.progressBar.getChildByName("spine_progress");
        let toX = -w/2 + percent * w;
        if(needTransform) {
            cc.tween(spine)
                .to(0.5, {x:toX})
                .start();
        }else {
            spine.x = -w/2 + percent * w;
        }
    },

    /**
     * 进入收集游戏动画
     */
    async showEnterCollectGameAni() {
        // 能量挤满进度条
        this.spine_full.node.active = true;
        await new Promise(res=>{
            this.spine_full.setAnimation(0, "animation", false);
            this.spine_full.setCompleteListener(()=>{
                this.spine_full.setCompleteListener(null);
                this.spine_full.node.active = false;
                res();
            });
        });
        await new Promise(res=>{
            let btn_enter_spine = this.btn_enter.getComponent(sp.Skeleton);
            btn_enter_spine.setAnimation(0, "animation2", false);
            btn_enter_spine.setCompleteListener(()=>{
                btn_enter_spine.setCompleteListener(null);
                btn_enter_spine.setAnimation(0, "animation1", false);
                res();
            });
        });
    }
});
