cc.Class({
    extends: require("LMSlots_Slots_Base"),

    properties: {
        _delaytimes:0
    },

    //重写
    StartMove:function(){
        this._super();
        let spindata = SlotsFacade.dm.getSpinData();
        if(spindata){
            this._delaytimes = SlotsFacade.extraWildCmp.hideWilds();
        }
        if(SlotsFacade.dm.GetTotalFree() == 0) {
            SlotsFacade.soundMgr.playBgm();
        }
        this.scheduleOnce(()=>{
            this.playAni_xztw();
        }, 0.9);
    },

    //重写停止移动
    StopMove:function(){
        this._super();
        //直接显示掉落
        SlotsFacade.extraWildCmp.showZengjiaWild(SlotsFacade.dm.getSpinData().fallList);

    },
    /**P
     * 播放宝箱
     */
    playAni_xztw() {
        let spine = this.node.getChildByName("spine_xiangzituowei").getComponent(sp.Skeleton);
        spine.node.active = true;
        spine.setAnimation(0, "animation", false);
        spine.setCompleteListener(()=>{
            spine.setCompleteListener(null);
            spine.node.active = false;
        });
    },

    /**
     * @override
     * @param {*} msg 
     */
    async onMsgSpine(msg){
        await SlotsFacade.delayTime(this._delaytimes)
        SlotsFacade.extraWildCmp.startFallWild(SlotsFacade.dm.getSpinData().fallList);
        //SlotsFacade.flowCtrl.onMsgSpine(msg);
        this._gameInfo = msg;
        this.SetSlotsResult(msg.resultCards);
        this.SetReelStateInfo(msg.resultCards);
    },

    //重写：显示bonus中奖
    OnSpinEnd:function(){
        SlotsFacade.flowCtrl.spinEnd();
    },

    /**
     * @override
     */
    ReconnectShow:function(){
        this.scheduleOnce(()=>{
            SlotsFacade.flowCtrl.enterRoom();
        });
    },

    /**
     * 播放scatter 中奖动画
     */
    async playScatter(indexs) {
        SlotsFacade.soundMgr.playEffect("bell");
        indexs.forEach(element => {
            let item = this.GetSymbolByIdx(element);
            item.playTriggerAnimation()
        });
        await SlotsFacade.delayTime(1.5);
    },

    /**
     * 批量获取symbol
     */
    getSymbolsByServerIds(ids) {
        let ret = [];
        ids.forEach(element => {
            ret.push(this.GetSymbolByIdx(element));
        });
        return ret;
    },

    clearAllSymbolAniState() {
        for(let i=0; i<this._reels.length; i++) {
            let symbols = this._reels[i]._symbols;
            for(let j=0; j<symbols.length; j++) {
                symbols[j].StartMove();
            }
        }
    },

    //播放宝箱进入动画
    async playBaoxiangJinChang(){
        this.clearAllSymbolAniState();
        return new Promise((success)=>{
            let num = 5;
            let reel = this._reels[2];
            reel._bMoving = true;
            reel._stopTime = 0.8*num;
            let jinchang = ()=> {
                let baoxiang = cc.find('spine_baoxianxiangjinchang', this.node);
                if(num <= 0){
                    baoxiang.active = false;
                    success();
                }else{
                    baoxiang.scale = (num%2 == 1) ? 1:-1;
                    SlotsFacade.dm.playSpine(baoxiang,'animation',false,()=>{
                        this.changeSymobl();
                    });
                    this.scheduleOnce(()=>{
                        num -= 1;
                        jinchang();
                    },0.8);
                }
            }
            jinchang();

        })
    },

    //修改符号
    changeSymobl(){
        let symbols = this._reels[2]._symbols;
        symbols[2].changeSymboltoBaoxiang();
    },
});
