let takeCfg = {
    [1]: { multiple: 3 },
    [2]: { multiple: 5 },
    [3]: { multiple: 7 },
    [4]: { multiple: 9 },
    [5]: { multiple: 12 },
    [6]: { multiple: 20 },
    [7]: { multiple: 2 },
    [8]: { multiple: 4 },
    [9]: { multiple: 6 },
    [10]: { multiple: 8 },
    [11]: { multiple: 10 },
    [12]: { multiple: 15 },
    [13]: { multiple: 30 },

    [14]: { multiple: 50 },
    [15]: { multiple: 60 },
    [16]: { multiple: 70 },
    [17]: { multiple: 80 },
    [18]: { multiple: 90 },
    [19]: { multiple: 100 },
    [20]: { multiple: 150 },
    [21]: { multiple: 200 },
    [22]: { multiple: 300 },
    [23]: { multiple: 500 },
    [24]: { multiple: 750 },
    [25]: { multiple: 1000 },
    [26]: { multiple: 1500 },
};
/**
 * 收集游戏
 * @class DoubleAgent_CollectGame
 */
cc.Class({
    extends: cc.Component,

    properties: {
        panel: cc.Node,
        bagListNode: cc.Node,
        multipleListNode: cc.Node,
        btnOk: cc.Button,
        title: cc.Node,
        guide: cc.Node,
        pre_offers_node: cc.Node,
        dialog_result: cc.Node,
        dialog_result2: cc.Node,
        dialog_round_tips: cc.Node,
        tips_have_select: cc.Node,
        money_bag_selected: cc.Node, // 第一个选中的钱袋
        money_bag: cc.Node,  // 用于重复选择显示的钱袋
        particle_feixing: cc.ParticleSystem,

        _bagList: null,
        _multipleList: null,
        _callBack: null,
        _data: null, // 收集游戏数据
        _multipleChoiceBagCnt: 7,
    },

    onLoad() {
        this._bagList = [];
        this._multipleList = [];
        this._reset();
        for (let i = 1; i <= this._data.bagCnt; i++) {
            let item = this.bagListNode.getChildByName("take_bag_" + i);
            item.data = {};
            item.data.id = i;
            item.active = false;
            item.getChildByName("label").getComponent(cc.Label).string = i.toString();
            item.on(cc.Node.EventType.TOUCH_END, this._onClickBag.bind(this), this);
            this._bagList.push(item);

            let multipleItem = this.multipleListNode.getChildByName("take_multiple_" + i);
            if (i > 13) {
                multipleItem.getChildByName("bg").getComponent("ImgSwitchCmp").setIndex(1);
            }
            multipleItem.getChildByName("label").getComponent(cc.Label).string = takeCfg[i].multiple + "X";
            this._multipleList.push(multipleItem);
        }

        this.btnOk.node.on("click", () => {
            this.close();
        });
        this.dialog_result.getChildByName("content").getChildByName("btn_ok").on("click", this._onTakeHandler.bind(this), this)
        this.dialog_result.getChildByName("content").getChildByName("btn_no").on("click", this._onLeaveItHandler.bind(this), this)

        this.dialog_result2.getChildByName("content").getChildByName("btn_ok").on("click", this._onKeepHandler.bind(this), this)
        this.dialog_result2.getChildByName("content").getChildByName("btn_no").on("click", this._onTradeHander.bind(this), this)

        this.money_bag_selected.data = { x: this.money_bag_selected.x, y: this.money_bag_selected.y, scaleX: this.money_bag_selected.scaleX, scaleY: this.money_bag_selected.scaleY };
    },

    _reset() {
        this._data = {
            bagCnt: 26,  // 总钱袋数量
            bagState: 0, // 0-不能点击 1-选择福袋 2-选择多个福袋子
            firstBagId: 0, // 第一个选择的钱袋id
            selectedIds: [], // 已选中的钱袋id
            curSelectedIds: [],  //多次选择时选中的钱袋id
            currRoundSelectedCnt: 0, // 当前论次选择了多少个钱袋
        };
        this._setTitleState(0);
        this.pre_offers_node.active = false;
        this.dialog_result.active = false;
        this.dialog_round_tips.active = false;
        this.tips_have_select.active = false;
        this.money_bag_selected.active = false;
        this.money_bag.active = false;
        this.particle_feixing.node.active = false;

        for (let i = 1; i <= this._data.bagCnt; i++) {
            let item = this.bagListNode.getChildByName("take_bag_" + i);
            item.active = false;
        }
    },

    close() {
        SlotsFacade.soundMgr.playEffect("bonus_close");
        if (SlotsFacade.dm.hasFree()) {
            SlotsFacade.soundMgr.playBgm("free_bgm");
        } else {
            SlotsFacade.soundMgr.playBgm();
        }
        this.panel.stopAllActions();
        this.panel.runAction(cc.sequence(cc.fadeOut(0.3), cc.callFunc(() => {
            this.panel.active = false;
        })));
        if (this._callBack) {
            this._callBack();
        }
    },

    //断线重连收集游戏state = 0, -- 记录当前状态，0代表收集状态，1代表选择第一个奖杯状态，2代表选择奖杯状态，
    //3代表中间选择奖励状态，4代表最终选择奖励状态
    async reConnectCollect(freebags) {
        this.btnOk.node.active = false;
        let state = freebags.currState.state;


        SlotsFacade.soundMgr.playBgm("bonus_bgm");
        //顶部位置显示
        this.guide.active = false;
        this.pre_offers_node.active = true;

        //显示界面/剩余选择次数
        this.panel.active = true;
        this.title.active = false;
        if (freebags.currState.nextCount) {
            this.tips_have_select.active = true;
            this.tips_have_select.getChildByName("label").getComponent(cc.Label).string = "0/" + freebags.currState.nextCount;
        } else {
            this._setTitleState(1)
        }

        //已经选择的钱包不用显示
        for (let i = 0; i < this._data.bagCnt; i++) {
            if (!freebags.choices.includes(i + 1)) {
                this._bagList[i].active = true;
            }
        }
        //已经出现的倍率置灰
        this.reConnectChoiceGray(freebags.unpickedMult);
        for (let i = 0; i < freebags.historyMult.length; i++) {
            this._showMultToOffers(freebags.historyMult[i], i + 1);
        }

        //第一个点击的钱袋光效
        if (freebags.lastChoice.length > 0) {
            this.money_bag_selected.active = true;
            cc.find("bag1/label", this.money_bag_selected).getComponent(cc.Label).string = freebags.lastChoice[0];
        }
        //控制参数
        this._multipleChoiceBagCnt = freebags.currState.nextCount;
        this._data.selectedIds = freebags.choices;

        if (state == 1) {
            this._data.bagState = 1;
        } else {
            this._data.bagState = 2;
            if (state == 3) {
                //要显示take it/leave it选择界面
                this._showBagResult(freebags);
            } else if (state == 4) {
                this._lastchoices = freebags.lastChoice;
                this.showLastChoiceUI(this._lastchoices);
            }
        }
    },

    //置灰已经选择的钱包
    reConnectChoiceGray(pickedmult) {
        this.initShowMultipleIcon(true);
        pickedmult.forEach(mult => {
            let itemidx = this.getTakemultipleItem(mult);
            let bgnode = cc.find(cc.js.formatStr('take_multiple_%s/bg', itemidx), this.multipleListNode);
            let lblnode = cc.find(cc.js.formatStr('take_multiple_%s/label', itemidx), this.multipleListNode);
            //item本身置灰
            bgnode.color = cc.color(255, 255, 255);
            lblnode.color = cc.color(255, 255, 255);
        });
    },

    async open(isView, cb) {
        this._callBack = cb;
        this.btnOk.node.active = isView;
        this.panel.active = true;
        this.panel.opacity = 0;
        this.panel.runAction(cc.fadeIn(0.3));
        this._showBagList();
        this.initShowMultipleIcon(true);
        this.guide.active = true;
        if (!isView) {
            await this._cmpleteBag();
            if (SlotsFacade.dm.getFreeBagInfo().currCnt == this._data.bagCnt) {
                this.initShowMultipleIcon(false);
                this._startTakeBonus();
            } else {
                this.close();
            }
        }
    },

    //初始化置灰倍率图标
    initShowMultipleIcon(isgray) {
        for (let i = 1; i <= this._data.bagCnt; i++) {
            let bgnode = cc.find(cc.js.formatStr('take_multiple_%s/bg', i), this.multipleListNode);
            let lblnode = cc.find(cc.js.formatStr('take_multiple_%s/label', i), this.multipleListNode);
            //item本身置灰
            if (isgray) {
                bgnode.color = cc.color(90, 90, 90);
                lblnode.color = cc.color(90, 90, 90);
            } else {
                bgnode.color = cc.color(255, 255, 255);
                lblnode.color = cc.color(255, 255, 255);
            }
        }
    },

    /**
     * 显示完成的个数
     * @param {*} cmpCnt 
     */
    _showBagList() {
        let cmpCnt = SlotsFacade.dm.getFreeBagInfo().currCnt;
        for (let i = 0; i < cmpCnt; i++) {
            this._bagList[i].active = true;
        }
    },

    /**
     * 完成一个钱袋
     */
    async _cmpleteBag() {
        let freeBags = SlotsFacade.dm.getFreeBagInfo();
        freeBags.currCnt += 1;
        if (freeBags.currCnt > this._data.bagCnt) {
            freeBags.currCnt = this._data.bagCnt;
        }
        let completeIndex = freeBags.currCnt - 1;
        let bagItem = this._bagList[completeIndex];
        await new Promise(res => {
            cc.tween(this.node)
                .delay(0.5)
                .call(() => {
                    bagItem.active = true;
                    let qiandaichuxian = this.bagListNode.getChildByName("qiandaichuxian").getComponent(sp.Skeleton);
                    qiandaichuxian.node.x = bagItem.x;
                    qiandaichuxian.node.y = bagItem.y;
                    qiandaichuxian.node.active = true;
                    qiandaichuxian.setAnimation(0, "animation", false);
                    qiandaichuxian.setCompleteListener(() => {
                        qiandaichuxian.setCompleteListener(null);
                        qiandaichuxian.node.active = false;
                    });
                })
                .delay(1.5)
                .call(() => {
                    res();
                })
                .start();
        });
    },

    /**
     * 设置标题状态
     */
    _setTitleState(value) {
        this.title.active = true;
        if (value == 1) {
            this.title.getComponent("ImgSwitchCmp").setIndex(1);
            cc.tween(this.title).repeatForever(
                cc.tween().to(0.8, { scale: 0.8 }).to(0.8, { scale: 1 })
            ).start();
        } else {
            this.title.getComponent("ImgSwitchCmp").setIndex(0);
            this.title.stopAllActions();
            this.title.scale = 1;
        }
    },

    /**
     * 开始进行bonus游戏流程
     */
    _startTakeBonus() {
        SlotsFacade.soundMgr.playBgm("bonus_bgm");
        this.guide.active = false;
        this.pre_offers_node.active = true;
        this._setTitleState(1);
        this._data.bagState = 1;
    },

    /**
     * 点击钱袋
     */
    _onClickBag(evt) {
        SlotsFacade.soundMgr.playEffect("bag_click");
        if (this._data.bagState == 0) {
            return;
        }
        if (this._data.bagState == 1) {
            this._data.bagState = 0;
            this._selectBag(evt.target);
            this._setTitleState(0);
        } else if (this._data.bagState == 2) {
            this._selectMultipleBag(evt.target);
        }
    },

    /**
     * 选择第一个幸运钱袋
     */
    async _selectBag(bagItem) {
        SlotsFacade.soundMgr.playEffect("bag_fly");
        this._data.firstBagId = bagItem.data.id;
        this._data.selectedIds.push(this._data.firstBagId);
        let xuanzeqiandai = bagItem.getChildByName("xuanzeqiandai").getComponent(sp.Skeleton);
        xuanzeqiandai.node.active = true;
        // 播放钱袋动画
        await new Promise(res => {
            xuanzeqiandai.setAnimation(0, "animation", false);
            xuanzeqiandai.setCompleteListener(() => {
                xuanzeqiandai.setCompleteListener(null);
                xuanzeqiandai.node.active = false;
                bagItem.active = false;
                res();
            });
        })
        // 播放粒子运动动画
        let startPos = this.panel.convertToNodeSpaceAR(bagItem.convertToWorldSpaceAR(cc.v2(0, 0)));
        this.particle_feixing.node.active = true;
        this.particle_feixing.node.x = startPos.x;
        this.particle_feixing.node.y = startPos.y;
        let endPos = { x: this.money_bag_selected.data.x, y: this.money_bag_selected.data.y };
        let middlePos = {
            x: startPos.x + (endPos.x - startPos.x) / 2,
            y: startPos.y + (endPos.y - startPos.y) / 2
        };
        await new Promise(res => {
            cc.tween(this.particle_feixing.node)
                .to(0.8, { x: middlePos.x, y: middlePos.y })
                .call(() => {
                    this.particle_feixing.node.active = false;
                    res();
                })
                .start()
        });
        // 
        this.money_bag_selected.active = true;
        this.money_bag_selected.scale = 1;
        this.money_bag_selected.x = middlePos.x;
        this.money_bag_selected.y = middlePos.y;
        cc.find("bag1/label", this.money_bag_selected).getComponent(cc.Label).string = this._data.firstBagId.toString();
        let qiandaishouji = this.money_bag_selected.getChildByName("qiandaishouji").getComponent(sp.Skeleton);
        qiandaishouji.node.active = true;
        qiandaishouji.setAnimation(0, "animation", false);
        qiandaishouji.setCompleteListener(() => {
            qiandaishouji.setCompleteListener(null);
            qiandaishouji.node.active = false;
        });
        await new Promise(res => {
            cc.tween(this.money_bag_selected)
                .to(1, { x: endPos.x, y: endPos.y, scaleX: this.money_bag_selected.data.scaleX, scaleY: this.money_bag_selected.data.scaleY })
                .call(() => {
                    res();
                })
                .start();
        });

        let result = await SlotsFacade.dm.reqSubGame({ rtype: 3, act: 1, choices: [bagItem.data.id] });
        this._startSelectMultipleBag(result.data);
    },

    /**
     * 开始进入选择多钱袋流程
     */
    async _startSelectMultipleBag(data) {
        this._data.curSelectedIds = [];
        this._multipleChoiceBagCnt = data.nextCount;
        this.dialog_round_tips.active = true;
        this.dialog_round_tips.scale = 0;

        this.dialog_round_tips.getChildByName('label_1').getComponent(cc.Label).string = data.nextRound;
        this.dialog_round_tips.getChildByName('label_2').getComponent(cc.Label).string = data.nextCount;
        await new Promise(res => {
            cc.tween(this.dialog_round_tips)
                .to(1, { scale: 1 }, { easing: "backOut" })
                .delay(1.5)
                .to(0.5, { scale: 0 }, { easing: "backIn" })
                .call(() => {
                    this.dialog_round_tips.active = false;
                    res();
                })
                .start();
        });
        this.title.active = false;
        this.tips_have_select.active = true;
        this.tips_have_select.getChildByName("label").getComponent(cc.Label).string = "0/" + this._multipleChoiceBagCnt;
        this._data.bagState = 2;
    },

    /**
     * 选择多钱袋
     */
    _selectMultipleBag(bagItem) {
        let id = bagItem.data.id;
        if (this._data.selectedIds.includes(id)) {
            return;
        }
        this._data.selectedIds.push(id);
        this._data.curSelectedIds.push(id);
        this._data.currRoundSelectedCnt++;
        this.tips_have_select.getChildByName("label").getComponent(cc.Label).string = this._data.currRoundSelectedCnt + "/" + this._multipleChoiceBagCnt;
        let xuanzeqiandai = bagItem.getChildByName("xuanzeqiandai").getComponent(sp.Skeleton);
        xuanzeqiandai.node.active = true;
        xuanzeqiandai.setAnimation(0, "animation", false);
        if (this._data.currRoundSelectedCnt == this._multipleChoiceBagCnt) {
            this._data.bagState = 0;
            this.scheduleOnce(() => {
                this._processResult();
            }, 0.5);
        }
    },

    async _processResult() {
        this.tips_have_select.active = false;
        this._setTitleState(0);

        let result = await SlotsFacade.dm.reqSubGame({ rtype: 3, act: 2, choices: this._data.curSelectedIds });
        this.playChoiceResult(result.data);
    },

    //多钱袋选择结束 开始播放选择结果
    async playChoiceResult(data) {
        this.money_bag.active = true;
        let shownode = cc.find('shownode', this.money_bag);
        let bag1node = cc.find('shownode/bag1', this.money_bag);
        let bag2node = cc.find('shownode/bag2', this.money_bag);
        let moneybagcnt = 0;            //开启钱袋计数
        let self = this;
        let dataitems = data.items;
        let showmoneybag = function () {
            if (moneybagcnt >= self._multipleChoiceBagCnt) {
                //展示结束
                self.money_bag.active = false;
                self._showBagResult(data.freeBags);
            } else {
                let moneybagpos = self._data.curSelectedIds[moneybagcnt];

                //上面展示同时 下面钱袋要消失
                self.hideChoiceMoneyBag(moneybagpos);

                //渐变显示
                shownode.opacity = 0;
                shownode.runAction(cc.fadeIn(0.2));
                bag1node.active = true;
                bag1node.scale = 0;

                //设置label
                cc.find('label', bag1node).getComponent(cc.Label).string = moneybagpos;
                cc.tween(bag1node).to(0.5, { scale: 1 }, { easing: 'backOut' }).delay(1).call(() => {
                    bag2node.active = true;
                    bag1node.active = false;
                    let qiandaifanbei = cc.find('qiandaifanbei', bag2node);
                    SlotsFacade.dm.playSpine(qiandaifanbei, 'animation', false, () => {
                        qiandaifanbei.active = false;
                    });

                    //设置倍率 做放大效果
                    let multarr = dataitems[moneybagcnt];
                    let multratio = (multarr.length > 1) ? multarr[1] : multarr[0];
                    let lblnode = cc.find('label', bag2node);
                    lblnode.scale = 0;
                    lblnode.getComponent(cc.Label).string = multratio + "X";
                    cc.tween(lblnode).to(0.5, { scale: 1 }, { easing: 'backOut' }).call(() => {
                        if (multarr.length == 1) {
                            self.hideOutMult(multratio);
                        }
                    }).delay(2).call(() => {
                        multratio = multarr[0];
                        if (multarr.length > 1) {
                            //倍率数组大于1 需要两次展示倍率
                            self.hideOutMult(multratio);
                            lblnode.getComponent(cc.Label).string = multratio + "X";
                            //同时播放切换特效
                            let qiehuansp = cc.find('shuzhiqiehuan', bag2node);
                            SlotsFacade.dm.playSpine(qiehuansp, 'animation', false, () => {
                                //渐隐处理
                                shownode.runAction(cc.sequence(cc.delayTime(2), cc.fadeOut(0.5), cc.callFunc(() => {
                                    //继续下一个钱袋
                                    moneybagcnt++;
                                    bag2node.active = false;
                                    showmoneybag();
                                })));
                            });
                        } else {

                            //渐隐处理
                            shownode.runAction(cc.sequence(cc.fadeOut(0.5), cc.callFunc(() => {
                                //继续下一个钱袋
                                moneybagcnt++;
                                bag2node.active = false;
                                showmoneybag();
                            })));
                        }



                    }).start();


                }).start();
            }
        }
        showmoneybag();
    },

    //按倍率在multiplelist里获取take_multiple
    getTakemultipleItem(mult) {
        for (let i = 1; i <= this._data.bagCnt; i++) {
            if (takeCfg[i].multiple == mult)
                return i;
        }
    },

    //按倍率置灰已经出现的倍率
    hideOutMult(mult) {
        let itemidx = this.getTakemultipleItem(mult);
        if (!itemidx) {
            console.log('>>>> 倍率没找到:' + mult);
            return;
        }
        let bgnode = cc.find(cc.js.formatStr('take_multiple_%s/bg', itemidx), this.multipleListNode);
        let lblnode = cc.find(cc.js.formatStr('take_multiple_%s/label', itemidx), this.multipleListNode);
        let beishunode = cc.find(cc.js.formatStr('take_multiple_%s/beishuqubianhui', itemidx), this.multipleListNode);
        //item本身置灰
        bgnode.color = cc.color(90, 90, 90);
        lblnode.color = cc.color(90, 90, 90);
        SlotsFacade.dm.playSpine(beishunode, 'animation', false);
    },

    //按位置隐藏已经pick的钱袋
    hideChoiceMoneyBag(idx) {
        let item = this.bagListNode.getChildByName("take_bag_" + idx);
        item.getChildByName('xuanzeqiandai').active = false;
        item.active = false;
    },

    /**
     * 显示钱袋结果
     */
    async _showBagResult(freeBags) {
        SlotsFacade.soundMgr.playEffect("board_show");
        this.dialog_result.active = true;
        let content = this.dialog_result.getChildByName("content");
        content.active = false;
        content.getChildByName("label_1").getComponent(cc.Label).string = freeBags.mult + "X";
        let prizenum = Global.convertNumToShort(freeBags.prize, 1000, 0);
        let totalnum = Global.convertNumToShort(freeBags.prize * freeBags.mult, 1000, 0);
        content.getChildByName("label_2").getComponent(cc.Label).string = cc.js.formatStr('%s X %s = %s', freeBags.mult, prizenum, totalnum);

        let tips_node = this.dialog_result.getChildByName("tips_node");
        tips_node.active = true;
        tips_node.scale = 0;
        cc.tween(tips_node.getChildByName("tips")).repeatForever(
            cc.tween().to(0.8, { scale: 0.8 }).to(0.8, { scale: 1 })
        ).start();
        cc.tween(tips_node)
            .to(0.5, { scale: 1.26 }, { easing: "backOut" })
            .call(() => {
                content.active = true;
            })
            .delay(2)
            .to(0.5, { scale: 0 }, { easing: "backIn" })
            .call(() => {
                tips_node.active = false;
            })
            .start();
    },

    //继续选择显示倍率到pre_offers_node(参数开奖的倍数)
    _showMultToOffers(mult, index) {
        let multnode = cc.find(cc.js.formatStr('getmult/multshow_%s', index), this.pre_offers_node);
        multnode.getComponent(cc.Label).string = mult + 'X';
        multnode.scale = 0;
        cc.tween(multnode).to(0.3, { scale: 1 }, { easing: 'backOut' }).start();
    },

    //收集多钱袋选择结束点击 take it
    async _onTakeHandler() {
        SlotsFacade.soundMgr.playEffect("bonus_end_show");
        let result = await SlotsFacade.dm.reqSubGame({ rtype: 3, act: 3, takeIt: true });
        await SlotsFacade.popup.showCollectWinGold(result.data);
        SlotsFacade.dm.getFreeBagInfo().currCnt = 0;
        this._reset();
        this.close();
    },

    //收集多钱袋选择继续点击 leave it
    async _onLeaveItHandler() {
        let result = await SlotsFacade.dm.reqSubGame({ rtype: 3, act: 3, takeIt: false });
        let freebags = result.data.freeBags;
        if (freebags.currState.state == 4) {
            //最后一次选择
            this._lastchoices = freebags.lastChoice;
            this.showLastChoiceUI(this._lastchoices);
        } else {
            //继续选择
            this._startSelectMultipleBag(result.data);
        }

        this._showMultToOffers(freebags.mult, freebags.historyMult.length);
        this._data.currRoundSelectedCnt = 0;
        this.dialog_result.active = false;
    },

    //收集结果keep结果选择
    async _onKeepHandler() {
        let result = await SlotsFacade.dm.reqSubGame({ rtype: 3, act: 4, keep: true });
        await this._showSingleMoneybag(result.data, this._lastchoices[0]);
        await SlotsFacade.popup.showCollectWinGold(result.data);
        SlotsFacade.dm.getFreeBagInfo().currCnt = 0;
        this._reset();
        this.close();
    },

    //收集结果trade结果选择
    async _onTradeHander() {
        let result = await SlotsFacade.dm.reqSubGame({ rtype: 3, act: 4, keep: false });
        await this._showSingleMoneybag(result.data, this._lastchoices[1]);
        await SlotsFacade.popup.showCollectWinGold(result.data);
        SlotsFacade.dm.getFreeBagInfo().currCnt = 0;
        this._reset();
        this.close();
    },

    //展示单个钱袋结果
    async _showSingleMoneybag(data, choicepos) {
        return new Promise((success) => {
            let moneybag2 = cc.find('panel/money_bag2', this.node);
            moneybag2.active = true;
            let shownode = cc.find('shownode', moneybag2);
            let bag1node = cc.find('shownode/bag1', moneybag2);
            let bag2node = cc.find('shownode/bag2', moneybag2);

            bag1node.active = true;
            shownode.scale = 0;

            //设置label
            cc.find('label', bag1node).getComponent(cc.Label).string = choicepos;
            cc.tween(shownode).to(0.5, { scale: 1 }, { easing: 'backOut' }).delay(1).call(() => {
                bag2node.active = true;
                bag1node.active = false;
                let qiandaifanbei = cc.find('qiandaifanbei', bag2node);
                SlotsFacade.dm.playSpine(qiandaifanbei, 'animation', false, () => {
                    qiandaifanbei.active = false;
                });

                //设置倍率 做放大效果
                let lblnode = cc.find('label', bag2node);
                lblnode.scale = 0;
                lblnode.getComponent(cc.Label).string = data.mult + "X";
                cc.tween(lblnode).to(0.5, { scale: 1 }, { easing: 'backOut' }).delay(2).call(() => {
                    this.dialog_result2.active = false;
                    moneybag2.active = false;
                    success();
                }).start();
            }).start();
        })
    },

    //最后一次选择界面显示
    showLastChoiceUI(lastchoice) {
        cc.find('content/theme159_take_dialog5/label', this.dialog_result2).getComponent(cc.Label).string = lastchoice[0];
        cc.find('content/theme159_take_dialog4/label', this.dialog_result2).getComponent(cc.Label).string = lastchoice[1];
        this.dialog_result2.active = true;
    },

});
