let MOVESTATUS = {
    STATUS_MOVE: 0,          // 移动
    STATUS_NEEDSTOP: 1,      // 将要停止
    STATUS_MOVEBACK: 2,      // 回弹
    STATUS_REST: 3,          // 停顿一下
    STATUS_STOP: 4,          // 停止状态
};

/**
 * 滚动逻辑组件
 * @class DoubleAgent_ItemsNode
 */
cc.Class({
    extends: cc.Component,
    
    properties: {
        id:0,
        callBack        : null,     // 回调函数
        gameCfg         : null,     // 游戏配置
        items           : [],       // item的组件数组
        itemClass       : "",       // 转轴图标类
        itemsContainer  : null,     // 转轴容器节点
        itemsContainerRect:null,    // 转轴容器节点框Rect
        itemWidth       : 0,        // 单个转轴图标宽
        itemHeight      : 0,        // 单个转轴图标高
        activeItemsContainer:null, // 播放item相关行为的节点

        //配置
        col                 : 5,    // 列数
        row                 : 4,    // 行数
        spaceWidth          : 0,    // 列间隔
        speed               : 30,   // 移动速度
        moveBackSpace       : 40,   // 回弹距离
        firstColMinRoundCount: 2,   // 第一列开始启动自动旋停需要转的圈数
        spaceRoundCount     : 2,    // 开始启动悬停后列间启动悬停的间隔圈数
        colStateInfo        : null, // 转轴列状态信息
        canStartStop        : false,// 是否可启动停止流程

        lineActionNode      : null, // 控制线路action的节点

        resultIds         : null, // 卷轴最终结果

        spine_add_speed  : sp.Skeleton, // 加速spine动画
        _isManualStop   : false, // 是否手动停止
    },

    onLoad() {
        this.lineActionNode = new cc.Node();
        this.lineActionNode.parent = this.node;
    },

    /**
     * 初始化列数据状态信息
     */
    initColStateInfo() {
        this.colStateInfo = {};
        for(let i=0; i<this.col; i++) {
            let colStateInfoItem = {
                moveState       : MOVESTATUS.STATUS_STOP, // 当前所处的状态
                spinedRound     : 0,                      // 已经旋转的圈数
                needSpinRound   : 1000000000,             // 启动列停止流程需要旋转的圈数
                speed           : this.speed,             // 旋转速度
                needAddSpeed    : false,                  // 是否需要加速
                hasScatter      : false,                  // 是否有scatter
            };
            this.colStateInfo[i+""] = colStateInfoItem;
        }
    },

    /**
     * 重置列状态信息
     * @param moveState
     */
    resetColStateInfo(moveState) {
        for(let i in this.colStateInfo) {
            this.colStateInfo[i].moveState = moveState;
            this.colStateInfo[i].spinedRound = 0;
            this.colStateInfo[i].needSpinRound = 1000000000;
            this.colStateInfo[i].speed = this.speed;
            this.colStateInfo[i].needAddSpeed = false;
            this.colStateInfo[i].hasScatter = false;
        }
    },

    /**
     * 初始化items相关组件
     * @param cb
     * @param gameCfg
     * @param {string} itemClass 转轴图标类
     */
    init(cb, gameCfg, itemClass) {
        this.itemClass = itemClass;
        this.itemsContainer = this.node.getChildByName("items_container");
        this.gameCfg = gameCfg;
        this.col = this.gameCfg.col;
        this.row = this.gameCfg.row;
        this.callBack = cb;
        this.itemsContainerRect = this.itemsContainer.getBoundingBox();
        this.itemWidth = (this.itemsContainerRect.width - this.spaceWidth*(this.col-1))/this.col;
        this.itemHeight = this.itemsContainerRect.height / this.row;
        this.activeItemsContainer =  this.node.getChildByName("active_items_container");
        this.initColStateInfo();
        this._initItems();
        this._initSpine();
    },

    _initSpine() {
        let spineAddSpeedNode = this.activeItemsContainer.getChildByName("spine_add_speed");
        if(spineAddSpeedNode) {
            this.spine_add_speed = spineAddSpeedNode.getComponent(sp.Skeleton);
        }
    },

    _showAddSpeedAni(boo, colIndex) {
        if(!this.spine_add_speed) {
            return;
        }
        this.spine_add_speed.node.active = boo;
        if(boo) {
            this.spine_add_speed.setAnimation(0, "animation", true);
            let refNode = this.activeItemsContainer.getChildByName("active_item_" + (5+colIndex));
            this.spine_add_speed.node.x = refNode.x;
            //this.spine_add_speed.node.y = refNode.y;
            if(!this._isManualStop) {
                SlotsFacade.soundMgr.playEffect("reel_notify");
            }
        }
    },

    /**
     * 初始化 items
     */
    _initItems() {
        let activeItemsContainer = this.activeItemsContainer;

        let itemCount = this.col * this.row + this.col; //加一行数目无用的图标用作旋转过渡
        let activeItemTemplate = activeItemsContainer.getChildByName("active_item");
        for(let i=0; i<itemCount; i++) {
            let node = new cc.Node();
            node.addComponent(cc.Sprite);
            node.parent = this.itemsContainer;
            let cmp = node.addComponent(this.itemClass);
            cmp.gameCfg = this.gameCfg;
            cmp.itemId = -1;
            cmp.rowIndex = parseInt(i/this.col);
            cmp.colIndex = parseInt(i%this.col);
            cmp.logicIndex = i;
            if(i < itemCount - this.col) {
                let activeItem = cc.instantiate(activeItemTemplate);
                activeItem.active = true;
                activeItem.parent = activeItemsContainer;
                activeItem.name = "active_item_" + i;
                cmp.initActiveNode(activeItem);
            }
            this.updateItem(cmp, -1);
            this.items.push(cmp);
        }
        // 绑定图标上下行同列的节点
        for(let i=0; i<itemCount; i++) {
            let cmp = this.items[i];
            // 下一行
            let nextRow = cmp.rowIndex + 1;
            if(nextRow > this.row) {
                nextRow = 0;
            }
            let nextIndex = nextRow*this.col + cmp.colIndex;
            let nextRowNode = this.items[nextIndex].node;
            cmp.node.nextRowNode = nextRowNode;

            // 上一行
            let preRow = cmp.rowIndex - 1;
            if(preRow < 0) {
                preRow = this.row;
            }
            let preIndex = preRow*this.col + cmp.colIndex;
            let preRowNode = this.items[preIndex].node;
            cmp.node.preRowNode = preRowNode;
        }
        this.initItemsPos();
    },

    /**
     * 更新item图标
     * @param cmp
     * @param id
     */
    updateItem(cmp, id) {
        //todo 从公用轴中获取数据
        if(id<=0) {
            let idList = [1,3,4,5,6,7,8,9,10];
            id = idList[parseInt(Math.random()*idList.length)];
        }
        cmp.bind(id);
    },

    /**
     * 填充所有转轴图标
     */
    fillAllItemsSpr(ids) {
        this.resultIds = ids;

        let scatterCount = 0;
        for(let i=0; i<this.col; i++) {
            let key = i + "";
            let hasScatter = this._hasScatterInCol(i);
            this.colStateInfo[key].needAddSpeed = scatterCount >= 2;
            this.colStateInfo[key].hasScatter = hasScatter;
            if(hasScatter) {
                scatterCount++;
            }
        }

        for(let i=0; i<ids.length; i++) {
            this.updateItem(this.items[i], ids[i]);
        }
    },

    /**
     * 初始化图标位置
     *      从左到右从上到小一次排列
     */
    initItemsPos() {
        for(let i=0; i<this.items.length; i++) {
            let cmp = this.items[i];
            cmp.node.x = this.itemWidth * cmp.colIndex + this.spaceWidth * cmp.colIndex + this.itemWidth / 2;
            cmp.node.y = (-this.itemHeight/2 - this.itemHeight * cmp.rowIndex) + this.itemsContainerRect.height;
            if(cmp.activeNode) {
                cmp.activeNode.x = cmp.node.x;
                cmp.activeNode.y = cmp.node.y;
            }
        }
    },

    /**
     * 列中是否有scatter
     * @param colIndex
     * @private
     */
    _hasScatterInCol(colIndex) {
        for(let i=0; i<this.row; i++) {
            let id = this.resultIds[i*this.col + colIndex];
            if(id == this.gameCfg.scatterId) {
                return true;
            }
        }
        return false;
    },

    /**
     * 设置转轴列图标 最终位置
     * @param colIndex
     */
    setColStop(colIndex) {
        SlotsFacade.soundMgr.stopEffectByName("reel_notify");
        SlotsFacade.soundMgr.playEffect("reel_stop");
        for(let i=0; i<this.items.length; i++) {
            if(this.items[i].colIndex == colIndex) {
                let cmp = this.items[i];
                cmp.node.x = this.itemWidth * cmp.colIndex + this.spaceWidth * cmp.colIndex + this.itemWidth / 2;
                cmp.node.y = (-this.itemHeight/2 - this.itemHeight * cmp.rowIndex) + this.itemsContainerRect.height;
            }
        }
        if(this.colStateInfo[colIndex.toString()].hasScatter) {
            for(let i=0; i<this.gameCfg.row; i++) {
                let index = colIndex + i*this.gameCfg.col;
                let item = this.items[index];
                if(item.itemId == this.gameCfg.scatterId) {
                    SlotsFacade.soundMgr.playEffect("symbol_scatter");
                    item.playScatter(true);
                }
            }
        }

        this._showAddSpeedAni(false);
        if(colIndex + 1 < this.col) {
            let colInfo = this.colStateInfo[colIndex+1];
            if(colInfo.needAddSpeed) {
                colInfo.speed *= 2.5;
                this._showAddSpeedAni(true, colIndex + 1);
            }
        }
        if(this.isAllColSameMoveState(MOVESTATUS.STATUS_STOP)) {
            if(this.callBack) {
                SlotsFacade.soundMgr.stopEffectByName("reel_notify");
                SlotsFacade.soundMgr.playEffect("reel_stop");
                this.callBack({evt:"complete", target:this});
            }
        }
    },

    /**
     * 是否所有列处于某个移动状态
     * @returns {boolean}
     */
    isAllColSameMoveState(moveState) {
        for(let i in this.colStateInfo) {
            if(this.colStateInfo[i].moveState != moveState) {
                return false;
            }
        }
        return true;
    },

    update(dt) {
        // 修改items位置
        for(let i=0; i<this.items.length; i++) {
            let cmp = this.items[i];
            let colInfo = this.colStateInfo[cmp.colIndex];
            if(colInfo.moveState == MOVESTATUS.STATUS_MOVE) {
                cmp.node.y -= colInfo.speed;
            }else if(colInfo.moveState == MOVESTATUS.STATUS_MOVEBACK) {
                cmp.node.y += colInfo.speed/6;
            }
        }
        // 将超过底边的icon放到最上面
        for(let i=0; i<this.items.length; i++) {
            let cmp = this.items[i];
            let colInfo = this.colStateInfo[cmp.colIndex];
            if(colInfo.moveState == MOVESTATUS.STATUS_MOVE) {
                if(this.canStartStop && cmp.rowIndex == 0 && colInfo.spinedRound >= colInfo.needSpinRound) {
                    if(
                        cmp.node.y < this.itemsContainerRect.height - this.itemHeight/2 - this.moveBackSpace &&
                        cmp.node.y > this.itemHeight + this.itemHeight/2
                    ) {
                        colInfo.moveState = MOVESTATUS.STATUS_MOVEBACK;
                        this.colChangeToMoveBack(cmp.colIndex);
                    }
                }
                if(cmp.node.y < -this.itemHeight/2) {
                    // 如果是第0行超过底边说明已经移动了一圈
                    if(cmp.rowIndex == 0) {
                        colInfo.spinedRound++;
                    }
                    cmp.node.y = cmp.node.nextRowNode.y + this.itemHeight;
                }
            } else if(colInfo.moveState == MOVESTATUS.STATUS_MOVEBACK) {
                if(cmp.rowIndex == 0 && cmp.node.y > this.itemsContainerRect.height - this.itemHeight/2) {
                    colInfo.moveState = MOVESTATUS.STATUS_STOP;
                    this.setColStop(cmp.colIndex);
                }else if(cmp.node.y > this.itemsContainerRect.height + this.itemHeight/2) {
                    cmp.node.y = cmp.node.preRowNode.y - this.itemHeight;
                }
            }
        }
    },

    /**
     * 开始旋转
     */
    startMove() {
        this.clearActiveItems();
        this.canStartStop = false;
        this._isManualStop = false;
        this.resultIds = [];
        this.resetColStateInfo(MOVESTATUS.STATUS_MOVE);

        this.scheduleOnce(()=>{
            this.playAni_xztw();
        }, 0.9);
    },

    /**
     * 开始启动停止
     */
    toStartStop(ids) {
        this.canStartStop = true;
        this.fillAllItemsSpr(ids);
        let firstColStateInfo = this.colStateInfo[0]; //首列旋转状态信息
        let needRound = Math.max(this.firstColMinRoundCount, firstColStateInfo.spinedRound);
        firstColStateInfo.needSpinRound = needRound;
        for(let i=1; i<this.col; i++) {
            this.colStateInfo[i].needSpinRound = this.colStateInfo[i-1].needSpinRound + this.spaceRoundCount;
            if(this.colStateInfo[i].needAddSpeed) {
                this.colStateInfo[i].needSpinRound += 15;
            }
        }
    },

    /**
     * 手动停止
     */
    manualStop(ids) {
        this.canStartStop = true;
        this._isManualStop = true;
        this.fillAllItemsSpr(ids);
        this.initItemsPos();
        for(let i=0; i<this.col; i++) {
            let colStateInfo = this.colStateInfo[i];
            if(colStateInfo.moveState != MOVESTATUS.STATUS_STOP) {
                this.colStateInfo[i].spinedRound = this.colStateInfo[i].needSpinRound;
            }
        }
    },

    /**
     * 播放中奖路线
     * @param lineList 线路数据
     * @param playOneByOne
     * @returns {Promise<void>}
     */
    playLine(lineList, playOneByOne) {
        this.lineActionNode.stopAllActions();
        let itemsIndex = [];
        for(let i=0; i<lineList.length; i++) {
            itemsIndex = itemsIndex.concat(lineList[i].indexs);
        }
        let playAllAction = cc.callFunc(()=>{
            this.showBorder(itemsIndex);
            this.showActiveItemsAni(itemsIndex);
        });

        if(playOneByOne) {
            let delayAction = cc.delayTime(1.5);
            let actionArr = [playAllAction];
            for(let i=0; i<lineList.length; i++) {
                actionArr.push(delayAction);
                actionArr.push(cc.callFunc(()=>{this.playALine(lineList[i].indexs)}));
            }
            actionArr.push(delayAction);
            this.lineActionNode.runAction(cc.repeatForever(cc.sequence(...actionArr)));
        }else {
            this.lineActionNode.runAction(playAllAction);
        }
    },

    playALine(lineIndex) {
        for(let i=0; i<this.items.length; i++) {
            let item = this.items[i];
            item.showActiveAni(false);
            item.showBorder(false);
        }
        this.showBorder(lineIndex);
        this.showActiveItemsAni(lineIndex);
    },

    /**
     * 显示border
     * @param itemsIndex
     */
    showBorder(itemsIndex) {
        for(let i=0; i<itemsIndex.length; i++) {
            this.items[itemsIndex[i]-1].showBorder(true);
        }
    },

    /**
     * 显示中奖items动画
     * @param itemsIndex
     */
    showActiveItemsAni(itemsIndex) {
        for(let i=0; i<itemsIndex.length; i++) {
            this.items[itemsIndex[i]-1].showActiveAni(true);
        }
    },

    /**
     * 清空items动画
     */
    clearActiveItems() {
        this.lineActionNode.stopAllActions();
        for(let i=0; i<this.items.length; i++) {
            let item = this.items[i];
            item.showActiveAni(false);
            item.showBorder(false);
            item.showStaticIcon(-1);
        }
    },

    /**
     * 清空border
     */
    clearBorder() {
        for(let i=0; i<this.items.length; i++) {
            this.items[i].showBorder(false);
        }
    },

    /**
     * 通过下表获取Items节点
     * @param indexs
     * @returns {[]}
     */
    getItemsByIndex(indexs) {
        let ret = [];
        indexs.forEach(v => {
           ret.push(this.items[v-1]);
        });
        return ret;
    },

    /**
     * 播放宝箱
     */
    playAni_xztw() {
        let spine = this.node.getChildByName("spine_xiangzituowei").getComponent(sp.Skeleton);
        spine.node.active = true;
        spine.setAnimation(0, "animation", false);
        spine.setCompleteListener(()=>{
            spine.setCompleteListener(null);
            spine.node.active = false;
        });
    },

    /**
     * 播放宝箱进场动画
     */
    playAni_bxjc() {
        //todo
    },

    /**
     * 当列状态变为回弹时调用
     * @param {*} colIndex
     */
    colChangeToMoveBack(colIndex) {
        if(colIndex == 2) {
            let index = SlotsFacade.dm.getBoxIndex();
            if(index) {
                let item = this.items[index-1];
                let pos = item.activeNode.convertToWorldSpaceAR(cc.v2(0, 0));
                SlotsFacade.extraWildCmp.showBox(pos);
            }
        }
    },

    /**
     * 播放scatter 中奖动画
     */
    async playScatter(indexs) {
        SlotsFacade.soundMgr.playEffect("bell");
        indexs.forEach(element => {
            let item = this.items[element-1];
            item.playScatter()
        });
        await SlotsFacade.delayTime(1.5);
    }
});
