/**
 * 弹窗管理器
 * @class DoubleAgent_Popup
 */
cc.Class({
    extends: cc.Component,

    properties:{
        bg:cc.Node
    },

    onLoad() {

    },

    showBg(boo) {
        this.bg.active = boo;
    },

    /**
     * 显示赢取金币
     * @param {number} goldNumb 
     */
    async showWinGold(goldNumb) {
        SlotsFacade.soundMgr.playEffect("free_dialog_collect_show");
        this.showBg(true);
        let panel = this.node.getChildByName("dialog_free_win_coin");
        panel.active = true;
        panel.scale = 0;
        panel.getChildByName("label_coin").getComponent("LabelRollCmp").startRoll(0, goldNumb);
        let okBtn = panel.getChildByName("ok_btn");
        await new Promise(res=>{
            cc.tween(panel)
                .to(0.5, {scale:1}, {easing:"backOut"})
                .start();
            let handler = ()=>{
                SlotsFacade.soundMgr.playEffect("common_click");
                okBtn.off(cc.Node.EventType.TOUCH_END, handler);
                cc.tween(panel)
                    .to(0.5, {scale:0}, {easing:"backIn"})
                    .call(()=>{
                        this.showBg(false);
                        Global.SlotsSoundMgr.stopBgm();
                        SlotsFacade.topCmp.SetBackLobby(true);
                        //SlotsFacade.bottomCmp.CanDoNextRound();
                        res();
                    })
                    .start();
            };
            cc.vv.gameData.checkAutoPlay(okBtn, handler);
            okBtn.on(cc.Node.EventType.TOUCH_END, ()=>{
                okBtn.stopAllActions();
                handler();
            });
        });
    },

    /**
     * 显示赢取免费次数
     * @param {number} cnt  
     * @param {*} cnt 
     * @param {*} isFirstTrigger 是否是首次触发
     */
    async showWinFreeCnt(cnt, isFirstTrigger) {
        SlotsFacade.soundMgr.playEffect("free_dialog_start_show");
        this.showBg(true);
        let panel = this.node.getChildByName("dialog_free_cnt");
        panel.active = true;
        panel.scale = 0;
        panel.getChildByName("label_free_cnt").getComponent(cc.Label).string = cnt.toString();
        let okBtn = panel.getChildByName("ok_btn");
        okBtn.active = isFirstTrigger;
        await new Promise(res=>{
            let tw = cc.tween(panel);
            tw = tw.to(0.5, {scale:1}, {easing:"backOut"});
            if(isFirstTrigger) {
                let handler = ()=>{
                    SlotsFacade.soundMgr.playEffect("common_click");
                    okBtn.off(cc.Node.EventType.TOUCH_END, handler);
                    cc.tween(panel)
                        .to(0.5, {scale:0}, {easing:"backIn"})
                        .call(()=>{
                            this.showBg(false);
                            res();
                        })
                        .start();
                };
                cc.vv.gameData.checkAutoPlay(okBtn, handler);
                okBtn.on(cc.Node.EventType.TOUCH_END, ()=>{
                    okBtn.stopAllActions();
                    handler();
                });
            }else {
                tw = tw
                .delay(1)
                .to(0.5, {scale:0}, {easing:"backIn"})
                .call(()=>{
                    this.showBg(false);
                    res();
                });
            }
            tw.start();
        });
    },

    /**
     * 显示收集赢取金币
     * @param {number} goldNumb 
     */
    async showCollectWinGold(resultdata) {
        SlotsFacade.soundMgr.playEffect("free_dialog_collect_show");
        this.showBg(true);
        let panel = this.node.getChildByName("dialog_collect_win");
        panel.active = true;
        panel.scale = 0;
        let lblcoin = panel.getChildByName("lbl_coin");
        let lblgetdesc = panel.getChildByName("lbl_getdesc");
        Global.doRoallNumEff(lblcoin,0,resultdata.winCoin,1,null,null,0,true);
        //显示获取公式
        let prizenum = Global.convertNumToShort(resultdata.prize,1000,0);
        let totalnum = Global.convertNumToShort(resultdata.prize*resultdata.mult,1000,0);
        lblgetdesc.getComponent(cc.Label).string = cc.js.formatStr('%s X %s = %s',resultdata.mult,prizenum,totalnum);

        let okBtn = panel.getChildByName("btn_collect");
        await new Promise(res=>{
            cc.tween(panel)
                .to(0.5, {scale:1}, {easing:"backOut"})
                .start();
            let handler = ()=>{
                SlotsFacade.soundMgr.playEffect("common_click");
                okBtn.off(cc.Node.EventType.TOUCH_END, handler);
                cc.tween(panel)
                    .to(0.5, {scale:0}, {easing:"backIn"})
                    .call(()=>{
                        this.showBg(false);
                        Global.SlotsSoundMgr.stopBgm();
                        SlotsFacade.topCmp.SetBackLobby(true);
                        SlotsFacade.bottomCmp.CanDoNextRound();
                        res();
                    })
                    .start();
            };
            cc.vv.gameData.checkAutoPlay(okBtn, handler);
            okBtn.on(cc.Node.EventType.TOUCH_END, ()=>{
                okBtn.stopAllActions();
                handler();
            });
        });
    },
 })