/**
 * @class DoubleAgent_GameData
 */
cc.Class({
    extends: require("LMSlots_GameData_Base"),

    properties: {
        spinData    : null,   // 点击spin服务器返回的数据
        extraWildIndexs:[], // extraWild下标
        energyData  : null,   // 能量数据
    },

    init(data, gameId) {
        this._super(data, gameId);
        this.energyData = this._deskInfo.energyData;
    },

    OnRcvNetSpine(msg) {
        //msg =  {"nextBetLine":{"spcode":500},"c":44,"code":200,"betcoin":10000,"wincoin":29500,"fallList":[[1,1],[1],[1],[],[1]],"spEffect":{"wincoin":29500,"kind":0},"randomData":{"bankWilds":[2,5,4],"fallWilds":[[1],[],[],[],[]]},"spLuXian":0,"subGameInfo":{"isMustJoin":-1,"subGamid":-1},"addMult":1,"scatterZJLuXian":{"mult":0,"coin":0,"indexs":[]},"coin":4533036,"mults":[10000,20000],"spcode":200,"lastBetCoin":4503536,"energyData":{"currRoundValue":6,"cmpInfo":{"prize":10000,"next_game":1},"totalCoin":10,"needCoins":5,"needBetIdx":1},"freeResult":{"freeInfo":[],"triFreeCnt":0},"pooljp":0,"freeCnt":0,"zjLuXian":[{"mult":1,"coin":2000,"indexs":[1,2,3,4],"card":7,"xlid":1},{"mult":1,"coin":2000,"indexs":[1,2,8],"card":4,"xlid":2},{"mult":1,"coin":1000,"indexs":[11,12],"card":3,"xlid":17},{"mult":1,"coin":1000,"indexs":[11,12],"card":3,"xlid":18},{"mult":1,"coin":1000,"indexs":[11,12],"card":3,"xlid":19},{"mult":1,"coin":1000,"indexs":[11,17],"card":3,"xlid":20},{"mult":1,"coin":1000,"indexs":[11,17],"card":3,"xlid":21},{"mult":1,"coin":1000,"indexs":[16,12],"card":3,"xlid":22},{"mult":1,"coin":1000,"indexs":[16,12],"card":3,"xlid":23},{"mult":1,"coin":1000,"indexs":[16,12],"card":3,"xlid":24},{"mult":1,"coin":1000,"indexs":[16,17],"card":3,"xlid":25},{"mult":1,"coin":1000,"indexs":[11,12],"card":3,"xlid":26},{"mult":1,"coin":5000,"indexs":[1,2,3,4,5],"card":7,"xlid":27},{"mult":1,"coin":1000,"indexs":[11,12],"card":3,"xlid":29},{"mult":1,"coin":1000,"indexs":[16,17],"card":3,"xlid":30},{"mult":1,"coin":500,"indexs":[1,2,3],"card":7,"xlid":31},{"mult":1,"coin":2000,"indexs":[1,2,8],"card":4,"xlid":32},{"mult":1,"coin":1000,"indexs":[11,12],"card":3,"xlid":45},{"mult":1,"coin":1000,"indexs":[11,12],"card":3,"xlid":46},{"mult":1,"coin":1000,"indexs":[11,17],"card":3,"xlid":47},{"mult":1,"coin":1000,"indexs":[16,12],"card":3,"xlid":48},{"mult":1,"coin":1000,"indexs":[16,12],"card":3,"xlid":49},{"mult":1,"coin":1000,"indexs":[16,12],"card":3,"xlid":50}],"allFreeCnt":0,"freeWinCoin":0,"resultCards":[10,5,7,6,10,10,5,4,10,3,3,3,4,10,3,3,3,11,10,4]}
        if(msg.code == 200){
            this.energyData = msg.energyData;
            if(msg.randomData && msg.randomData.wild_idxs) {
                this.extraWildIndexs = msg.randomData.wild_idxs;
            }else {
                this.extraWildIndexs = null;
            }
        }
        this._super(msg);
    },

    getSpinData() {
        return this._gameInfo;
    },

    /**
     * 是否可以收集
     * @returns {boolean}
     */
    canCollect() {
        return this.GetBetIdx() >= this.energyData.needBetIdx;
    },

    /**
     * 获取结果中收集图标得的下标
     */
    getCollectSymbolIndexs() {
        let resultCards = this.getSpinData().resultCards;
        if(!resultCards || resultCards.length < 1) {
            return [];
        }
        let ret = [];
        resultCards.forEach((v, i)=>{
            if(v == 3) {
                ret.push(i+1);
            }
        });
        return ret;
    },

    ///////////////////////免费相关//////////////////////////////
    /**
     * 是否有免费
     * @returns {boolean}
     */
    hasFree() {
        return this.GetFreeTime() > 0;
    },

    /**
     * 是否触发免费
     */
    isTriggerFree() {
        return this.triggerFreeCnt() > 0;
    },

    /**
     * 获取触发免费次数
     */
    triggerFreeCnt() {
        let freeResult = this.getSpinData().freeResult;
        if(freeResult && freeResult.triFreeCnt  && freeResult.freeInfo && freeResult.freeInfo.freeCnt) {
           return freeResult.freeInfo.freeCnt;
        }
        return 0;
    },
    
    /**
     * 是否是第一次触发免费
     */
    isFistTriggerFree() {
        return this.hasFree() && this.GetFreeTime() == this.GetTotalFree();
    },

    /**
     * 是否是最后一轮免费(旋转完成)
     */
    isLastEndFree() {
        return this.GetFreeTime() == 0 && this.GetTotalFree() > 0;
    },

    /**
     * 触发免费游西 获取scatter 下标
     */
    getScatterIndexs() {
        if(this.triggerFreeCnt() > 0) {
            return this.getSpinData().freeResult.freeInfo.scatterIdx.concat();
        }
        return [];
    },

    /**
     * 获取免费赢取的金币
     */
    getFreeWinCoin() {
        return this._gameInfo.freeWinCoin;
    },
    /////////////////////////随机wild相关//////////////////////////////
    /**
     * 获取宝箱坐标
     */
    getBoxIndex() {
        let resultCards = this.getSpinData().resultCards;
        if(resultCards[2] == 11) {
            return 3;
        }
        if(resultCards[7] == 11) {
            return 8;
        }
        if(resultCards[12] == 11) {
            return 13;
        }
        if(resultCards[17] == 11) {
            return 18;
        }
        return 0;
    },

    /**
     * 获取缺失wild拼图列
     */
    getLackPuzzleWildCols() {
        let fallList = this.getSpinData().fallList;
        let cols = [];
        for(let i=0; i<fallList.length; i++) {
            if(fallList[i].length < 1) {
                cols.push(i);
            }
        }
        return cols;
    },

    /**
     * 是否已经完成
     */
    isCompletePuzzelWild() {
        let boxIndex = this.getBoxIndex();
        if(boxIndex) {
            return true;
        }
        let fallList = this.getSpinData().fallList;
        if(fallList.length != 5) {
            return false;
        }
        for(let i=0; i<fallList.length; i++) {
            if(!fallList[i].length) {
                return false;
            }
        }
        return true;
    },

    ///////////////////////////收集相关/////////////////
    /**
     * 收集游戏最小下注
     * @returns {{singleBet: number, mult: number, line: DoubleAgent_GameData._deskInfo.line, isMax: boolean}}
     */
    getMinCollectBet() {
        if(this.energyData.needBetIdx > this.canBetList.length) {
            return null;
        }
        let ret = {
            singleBet:0,    // 单线下注额
            mult:0,         // 单线下注额 在可下注列表中的下标
            line:this.currLine, // 线数
            isMax:false          // 是否是最大值
        };
        let index = this.colection.needBet - 1;
        ret.singleBet = this.canBetList[index];
        ret.mult = index;
        return ret;
    },

    /**
     * 获取当前收集进度
     */
    getCollectPercent() {
        if(!this.energyData) {
            return 0;
        }
        return this.energyData.totalCoin / this.energyData.needCoins;
    },

    /**
     * 钱袋数据
     */
    getFreeBagInfo() {
        return this._deskInfo.freeBags;
    },

    ///////////////////////////////////////////////////////////////////////////
    /**
     * 请求子游戏数据51
     * @param gameType
     */
    reqSubGame(dt) {
        return new Promise(res=>{
            let req = {
                c:MsgId.SLOT_SUBGAME_DATA,
                gameid:this._gameId,
                data:dt
            };
            let resp = (msg)=>{
                cc.vv.NetManager.unregisterMsg(MsgId.SLOT_SUBGAME_DATA, resp, false, this);
                res(msg);
            }
            cc.vv.NetManager.registerMsg(MsgId.SLOT_SUBGAME_DATA, resp, this);
            cc.vv.NetManager.send(req, true);
        });
    },

    /**
     * 获取bigwin类型
     * @param {*} winCoin 
    */
    getBigWinType(winCoin) {
        let mul = winCoin/this.singleBet;
        let type = -1;
        if(mul >= 100) {
            type = 5;
        }else if(mul >= 80) {
            type = 4;
        }else if(mul >= 60) {
            type = 3;
        }else if(mul >= 40) {
            type = 2;
        }else if(mul >= 20) {
            type = 1;
        }else if(mul >= 10) {
            type = 0;
        }
        return type;
    },

    //按节点播放spine
    playSpine:function(node,aniName,loop,endCall){
        if(node){
            node.active = true
            let ske = node.getComponent(sp.Skeleton)
            if(ske){
                ske.setAnimation(0,aniName,loop)
                ske.setCompleteListener(() => {
                    if(endCall){
                        endCall()
                    }
                })
            }
        }
        
    },
});
